 static void Main(){var submitted=new ItemStack(1,3,"receipt-a");var changed=submitted.Clone();Assert(RebirthStationGridIngredients.IsSameStackSnapshot(changed,submitted),"Identical full submitted payload accepted");changed.itemValue.Metadata="receipt-b";Assert(!RebirthStationGridIngredients.IsSameStackSnapshot(changed,submitted),"Same type/count changed metadata rejected");changed=submitted.Clone();changed.itemValue.Mods=true;Assert(!RebirthStationGridIngredients.IsSameStackSnapshot(changed,submitted),"Same type/count changed mods rejected");changed=submitted.Clone();changed.count--;Assert(!RebirthStationGridIngredients.IsSameStackSnapshot(changed,submitted),"Changed submitted count rejected");var r=new Recipe();r.ingredients.Add(new ItemStack(1,4));var grid=new List<ItemStack>{new ItemStack(1,3,"A"),new ItemStack(1,7,"B")};RebirthStationGridIngredients.Plan plan;
