 ItemStack[] remainder;Assert(RebirthStationGridIngredients.TryBuildDebitedGrid(plan,grid,out remainder),"Admitted debit snapshot");Assert(remainder[0].IsEmpty()&&remainder[1].count==2&&remainder[1].itemValue.Metadata=="B","Exact paid slots and leftovers");remainder[1].itemValue.Metadata="detached";Assert(grid[1].itemValue.Metadata=="B","Debit result detached");grid[1].count++;Assert(!RebirthStationGridIngredients.TryBuildDebitedGrid(plan,grid,out remainder)&&remainder==null,"Changed slot count rejected");grid[1].count--;grid[1].itemValue.Metadata="substitution";Assert(!RebirthStationGridIngredients.TryBuildDebitedGrid(plan,grid,out remainder),"Same-type metadata substitution rejected");grid[1].itemValue.Metadata="B";Assert(grid[0].count==3&&grid[1].count==7&&r.ingredients[0].count==4,"No source mutation");grid[0].itemValue.Metadata="changed";Assert(plan.Inputs[0].Snapshot().itemValue.Metadata=="A","Detached input metadata");var snapshot=plan.Inputs[1].Snapshot();snapshot.itemValue.Metadata="changed";snapshot.count=999;Assert(plan.Inputs[1].Snapshot().itemValue.Metadata=="B"&&plan.Inputs[1].Snapshot().count==5,"Snapshot must not mutate plan");
 Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,3,1,out plan),"Insufficient inputs");grid.Add(new ItemStack(2,1));Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Extra ingredient rejects match");grid.RemoveAt(2);grid[0].itemValue.HasModSlots=true;grid[0].itemValue.Mods=true;Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Modified equipment excluded");grid[0].itemValue.Mods=false;Assert(RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Unmodified equipment permitted");
 grid[0].count=-1;Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Negative slot count rejected");grid[0].count=65536;Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Native ushort codec bound");grid[0].count=3;var validValue=grid[0].itemValue;grid[0].itemValue=null;Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Null item payload fails closed without native IsEmpty crash");grid[0].itemValue=validValue;grid.Add(new ItemStack(0,1));Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Positive count with none identity rejected");grid.RemoveAt(grid.Count-1); RebirthCraftingIngredientQuantity.Adjusted=2;Assert(RebirthStationGridIngredients.TryPlan(null,r,grid,2,1,out plan)&&plan.Inputs.Sum(x=>x.Count)==4,"Modified native quantities used");RebirthCraftingIngredientQuantity.Adjusted=0;Assert(RebirthStationGridIngredients.TryPlan(null,r,new List<ItemStack>(),1,1,out plan)&&plan.Inputs.Count==0,"Zero cost handled");RebirthCraftingIngredientQuantity.Adjusted=int.MaxValue;Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,2,1,out plan),"Overflow rejected");RebirthCraftingIngredientQuantity.Adjusted=-1;r.ingredients.Add(new ItemStack(1,int.MaxValue));Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Duplicate native requirements cannot overflow");r.ingredients.RemoveAt(1);r.materialBasedRecipe=true;Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Forge material ledger remains specialized");r.materialBasedRecipe=false;r.IsScrap=true;Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,1,1,out plan),"Scrapping excluded from exact crafting grid");r.IsScrap=false;Assert(!RebirthStationGridIngredients.TryPlan(null,r,Enumerable.Range(0,10).Select(x=>new ItemStack(0,0)).ToList(),1,1,out plan),"Grid bound");Assert(!RebirthStationGridIngredients.TryPlan(null,r,grid,0,1,out plan),"Batch bound");var recipes=new List<Recipe>{r};RebirthStationGridIngredients.Candidates("forge",recipes);Assert(XUiM_Recipes.Station=="forge"&&object.ReferenceEquals(XUiM_Recipes.Last,recipes),"Native catalogue filtering delegated");
